import unittest
from candidate import sum_product

class TestSumProduct(unittest.TestCase):
    def test_sum_product_empty_list(self):
        self.assertEqual(sum_product([]), (0, 1))

    def test_sum_product_normal_case_four_elements(self):
        self.assertEqual(sum_product([1, 2, 3, 4]), (10, 24))

    def test_sum_product_single_element(self):
        self.assertEqual(sum_product([5]), (5, 5))

    def test_sum_product_with_zero_returns_zero_product(self):
        self.assertEqual(sum_product([0, 1, 2]), (3, 0))

    def test_sum_product_all_negative_numbers(self):
        self.assertEqual(sum_product([-1, -2, -3]), (-6, -6))

    def test_sum_product_mixed_positive_and_negative(self):
        self.assertEqual(sum_product([-1, 2, -3]), (-2, 6))

    def test_sum_product_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            sum_product(None)

    def test_sum_product_invalid_type_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            sum_product("invalid")
